Step.Code:
public class QuestionConfiguration : IEntityTypeConfiguration<Question>
{
    public void Configure(EntityTypeBuilder<Question> builder)
    {
        builder.Property(q => q.Text).IsRequired().HasMaxLength(500);

        // YENİ
        builder.Property(q => q.Description).HasMaxLength(1000);
        builder.Property(q => q.Hint).HasMaxLength(300);

        builder.Property(q => q.Type).IsRequired();
        builder.Property(q => q.Points).IsRequired();

        builder.HasOne(q => q.Section)
            .WithMany(s => s.Questions)
            .HasForeignKey(q => q.SectionId)
            .OnDelete(DeleteBehavior.Cascade);
    }
}

